        uint8 savedAuthorityClass
    ) external {
        _check(c, 13);
        AttrState.Mutation memory m = StreamArtistAttestationTransport.confirmSanctionFinalized(
            _attestationStore(), msg.data
        );
        _commit(c, m.action, m.stateDelta, 0, 0);
