    /// @notice Permanent delegation evidence; the internal mapping retains its original physical slot.
    function recordDelegation(bytes32) external view returns (bytes32) {
        bytes32 recordHash;
        assembly ("memory-safe") { recordHash := calldataload(4) }
        return _recordDelegation[recordHash];
    }

    function _forwardConsentWriter() private {
        address target = consentWriterExtension;
        assembly ("memory-safe") {
            let pointer := mload(0x40)
            calldatacopy(pointer, 0, calldatasize())
            let success := delegatecall(gas(), target, pointer, calldatasize(), 0, 0)
            returndatacopy(pointer, 0, returndatasize())
            if iszero(success) { revert(pointer, returndatasize()) }
            return(pointer, returndatasize())
        }
    }

    function authorityDelegationHydrationState(AH.Query calldata q)
        external
        view
        returns (bytes memory)
    {
        return StreamArtistDelegationCollectionHydration.consentState(
            _policies, _recordDelegation, _saleRecords, _latestSaleConsents, q
        );
    }

    function authorityHydrationState(AH.Query calldata q)
        external
        view
        override
        returns (bytes memory)
    {
        bytes32[] memory records = new bytes32[](q.policies.length);
        for (uint256 j; j < records.length; ++j) {
            records[j] = _policies[
                keccak256(
                    abi.encode(q.collectionId, q.policies[j].phaseId, q.policies[j].policyHash)
                )
            ];
            if (records[j] == 0) revert T.InvalidRecord();
        }
        return abi.encode(records);
    }

    function authorityEconomicsHydrationState(
        AH.Query calldata q,
        T.EconomicsConsent[] calldata terms
    ) external view returns (bytes memory) {
        return StreamArtistEconomicsHydration.exportState(
            _policies,
            _economics,
            _associatedEconomicsRecords,
            _economicsAssociations,
            _recordDelegation,
            q,
            terms
        );
    }

    function authorityReadinessHydrationState(
        AH.Query calldata q,
        T.EconomicsConsent[] calldata economics
    ) external view returns (bytes memory) {
        bytes memory inner =
            StreamArtistEconomicsHydration.exportState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                _recordDelegation,
                q,
                economics
            );
        return StreamArtistContentHydration.exportState(
            _ratifications, _ratificationRecords, _contentConsents, _latestContentConsent, q, inner
        );
    }

    function _recoveredHydrationFeatures() internal pure override returns (uint256) {
        return XF.MULTIPLE_GENERATIONS_GRAPH_FEATURES | XF.UNBOUND_PLATFORM | XF.MULTIPLE_DISPUTE_HISTORY;
    }

    function recoveredAuthorityHydrationState(
        AH.Query calldata q,
        StreamArtistRecoveredHydrationTypes.OwnerProvenance calldata provenance
    ) external view override returns (bytes memory) {
        return StreamArtistRecoveredCollectionHydration.exportPolicies(
            _policies, _recordDelegation, q, provenance
        );
    }

    function _hydrateAuthority(AH.Query calldata q, AH.OwnerData calldata p) internal override {
        if (StreamArtistRecoveredHydrationCodec.isState(p.typedState, 6)) {
            if (_revision != 0 || p.nonces.length != 0) revert T.InvalidRecord();
            if (ConsentAggregate.applyState(_policies, _economics, _associatedEconomicsRecords, _economicsAssociations, _recordDelegation, _saleRecords, _latestSaleConsents, _contentConsents, _latestContentConsent, _royaltyFreezes, _contentFreezes, _latestContentFreeze, q, p.typedState)) return;
            if (MultipleImport.policies(_policies, _recordDelegation, q, p.typedState)) return;
            if (HistoryContentImport.selected(p.typedState)) {
                HistoryContentOwnerImport.applyState(
                    _sanctions,
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    _contentConsents,
                    _latestContentConsent,
                    _royaltyFreezes,
                    _contentFreezes,
                    _latestContentFreeze,
                    _ratifications,
                    _ratificationRecords,
                    q,
                    p.typedState
                );
                return;
            }
            if (RecoveredSanctions.selected(p.typedState)) {
                SanctionImport.importState(
                    _sanctions,
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    q,
                    p.typedState
                );
                return;
            }
            if (RecoveredContent.selected(p.typedState)) {
                RecoveredContent.Bundle memory imported = RecoveredContent.importState(
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    q,
                    p.typedState
                );
                RecoveredContent.importContent(
                    _contentConsents,
                    _latestContentConsent,
                    _royaltyFreezes,
                    _contentFreezes,
                    _latestContentFreeze,
                    _recordDelegation,
                    imported
                );
                if (RecoveredRatification.selected(p.typedState)) {
                    RecoveredRatification.importRecords(
                        _ratifications, _ratificationRecords, q, p.typedState
                    );
                }
                return;
            }
            if (StreamArtistRecoveredDelegatedConsentHydration.selected(p.typedState)) {
                StreamArtistRecoveredDelegatedConsentHydration.importState(
                    _policies,
                    _economics,
                    _associatedEconomicsRecords,
                    _economicsAssociations,
                    _recordDelegation,
                    _saleRecords,
                    _latestSaleConsents,
                    q,
                    p.typedState
                );
                return;
            }
            StreamArtistRecoveredEconomicsHydration.importEither(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                _recordDelegation,
                q,
                p.typedState
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MR.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            bytes memory delegation = StreamArtistMultipleRecordsConsentImport.economics(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                p.typedState
            );
            StreamArtistMultipleRecordsConsentImport.content(
                _ratifications,
                _ratificationRecords,
                _contentConsents,
                _latestContentConsent,
                p.typedState
            );
            StreamArtistMultipleDelegationCollectionHydration.consents(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, delegation
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, MD.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleDelegationCollectionHydration.consents(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, p.typedState
            );
            return;
        }
        if (StreamArtistDelegationHydrationCodec.tagged(p.typedState, DH.CONSENT)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistDelegationCollectionHydration.importConsent(
                _policies, _recordDelegation, _saleRecords, _latestSaleConsents, q, p.typedState
            );
            return;
        }
        if (StreamArtistMultipleHydrationCodec.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistMultipleCollectionHydration.policies(_policies, p.typedState);
            return;
        }
        if (StreamArtistContentHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            bytes memory inner = StreamArtistContentHydration.importState(
                _ratifications,
                _ratificationRecords,
                _contentConsents,
                _latestContentConsent,
                q,
                p.typedState
            );
            StreamArtistEconomicsHydration.importState(
                _policies, _economics, _associatedEconomicsRecords, _economicsAssociations, q, inner
            );
            return;
        }
        if (StreamArtistEconomicsHydration.isState(p.typedState)) {
            if (p.nonces.length != 0) revert T.InvalidRecord();
            StreamArtistEconomicsHydration.importState(
                _policies,
                _economics,
                _associatedEconomicsRecords,
                _economicsAssociations,
                q,
                p.typedState
            );
            return;
        }
        bytes32[] memory records = abi.decode(p.typedState, (bytes32[]));
        if (records.length != q.policies.length || p.nonces.length != 0) revert T.InvalidRecord();
        for (uint256 j; j < records.length; ++j) {
            bytes32 key = keccak256(
                abi.encode(q.collectionId, q.policies[j].phaseId, q.policies[j].policyHash)
            );
            if (_policies[key] != 0 || records[j] == 0) revert T.InvalidRecord();
            _policies[key] = records[j];
        }
    }
}

