    function _forwardIdentityRead() private view {
        _returnResolution(
            StreamArtistIdentityReadDispatch.read(
                _identity,
                _delegations,
                _identityRevisions,
                _rotations,
                _identityContests,
                _succession,
                _resolutions,
                _estate,
                _unavailability,
