            rows[k].rows = Reads.collectRows(
                c.source,
                c.scope.collections[k],
                RH.ownerProvenance(c.provenance, 6),
                c.economics[k],
                c.freezes[k],
                rows[k].bindings
            );
        }
        Validation.validate(rows, c.scope.collections, RH.ownerProvenance(c.provenance, 6));
        for (uint256 k; k < n; ++k) {
